```yaml
name: CLA Check

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

permissions:
  pull-requests: read

jobs:
  check-cla:
    name: Check CLA in PR description
    runs-on: ubuntu-latest
    steps:
      - name: Check for CLA text
        uses: actions/github-script@v7
        with:
          script: |
            const claText = "By submitting this pull request, I confirm that you can use, modify, copy, and redistribute this contribution, under the terms of your choice.";
            const prBody = context.payload.pull_request.body || "";

            if (!prBody.includes(claText)) {
              core.setFailed("Pull request description is missing the required CLA text.");
            } else {
              core.info("CLA text found in PR description.");
            }
```

